return {["Sheet1"]={},["Sheet2"]={},["npcs"]={["awardnpc001"]={["age"]=42,["appoint"]=1,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[她是欧阳敏，鸩羽山的名宿，近些年回归门派辅佐门主。她年轻时烟视媚行，是出名的大美人，有鸩羽妖姬之称，许多老一辈武林人士至今谈到她时还会露出一副心向往之的表情。]],["family"]=[[baituoshan]],["id"]=[[awardnpc001]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=26,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[欧阳敏]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[女]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[老娘年轻时也是远近皆知的大美人，可惜呀..;再美的容颜也顶不过这时光的摧残。]],["task"]=0,["wintext"]=[[你赢了]],["zhengqi"]=50},["awardnpc002"]={["age"]=60,["appoint"]=1,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[苦叶长老执掌普济院已经有二十多年，很多人都忘了他曾是个一言不合就开打、脾气暴烈的武僧，当年江湖人称其“怒目金刚”。]],["family"]=[[dali]],["id"]=[[awardnpc002]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=15,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[苦叶长老]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[阿弥陀佛，众生度尽，方成正觉。;唉，自从严施主来了之后，老衲便看守这普济院，如今已有二十余载。;龙树院那位，当年曾横压一代江湖高手，你若见到他，切记需以礼相待。]],["task"]=0,["wintext"]=[[你赢了]],["zhengqi"]=50},["awardnpc003"]={["age"]=55,["appoint"]=1,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[静院师太是静庭师太的师姐，为人和气、温婉，对后辈同门十分关爱。]],["family"]=[[emei]],["id"]=[[awardnpc003]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=21,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[静院师太]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[女]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[女孩子家行走江湖，得多加小心，遇事多点心眼，不可轻信于人。;唉，周天功再现于世，这世道，又不太平了。]],["task"]=0,["wintext"]=[[你赢了]],["zhengqi"]=50},["awardnpc004"]={["age"]=52,["appoint"]=1,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[丐帮九袋长老之一。都长老为人古板、不苟言笑，和做事经常不着调的鲁长老相比是另外一个极端。]],["family"]=[[gaibang]],["id"]=[[awardnpc004]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=19,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[都长老]],["n