=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[色即是空，空即是色。;柳玄风当年闯我天龙寺，杀伤我寺僧人无数，唉..现在想来，犹如昨日之事。;龙树院中困着一位施主，尔等无事万莫去打扰与他。]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc003"]={["age"]=50,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[静庭师太出自官绅之家，家学渊源，中年出家，自从执掌峨眉下院以来，法度严谨，各种事务都打理得井井有条，深受同门的敬服。]],["family"]=[[emei]],["id"]=[[tasknpc003]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=23,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[静庭师太]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[女]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[我峨眉乃是名门正派，岂能与奸邪为伍？;当年玄灵剑斩九煞为我峨眉在江湖之上挣得不少声名，尔等亦当如此。]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc004"]={["age"]=54,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[鲁长老壮年时身手高强，为前任帮主所倚重，后来因为一次江湖比斗而身负重伤，武功大不如前。执掌养心院以来，三天打鱼两天晒网，令帮主十分头疼。]],["family"]=[[gaibang]],["id"]=[[tasknpc004]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=20,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[鲁长老]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[做乞丐有什么不好， 落得个自在逍遥。;不疯魔，不成活！]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc005"]={["age"]=36,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[龙千慧是问情宫中生代的绝顶高手之一。她年少成名，年轻时美貌如花，又智计百出，加上出身名门，被江湖人尊称为大小姐。]],["family"]=[[gumu]],["id"]=[[tasknpc005]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=30,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[龙千慧]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[女]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[不要被身外物迷惑了你的心性。;十年生死两茫茫,不思量,自难忘, 千里孤坟,无处话凄凉，唉..]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc006"]={["age"]=45,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[成不骄长居紫霞峰，负责华山对外的一些俗务。他年轻时爱武成痴，性子又急切暴躁，为掌门所不喜，不过随着年岁渐长，也变得老成稳重许多。]],["family"]=[[huashan]],["id"]=[[tasknpc006]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=19,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[成不骄]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[你们手中的剑可不是烧火棍，华山威名不可轻侮。;我年轻时也曾想广大我华山门楣，但我天赋有限，唉..;华山的未来便交给你们了！]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc007"]={["age"]=40,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[白云子常年住在息心峰，他是门派里有名的琴痴。经常在深夜里，独自一人在峰顶，边抚琴，边弹剑长啸，宛如神仙中人。]],["family"]=[[kunlun]],["id"]=[[tasknpc007]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=25,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[白云子]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[我们昆仑派虽处边疆，但和中原武林一向联系紧密、互通有无。;习武之暇别忘了练琴，莫坠了我昆仑琴剑双绝的名头。;大敌当前，一手抚琴，一手持剑，那是何等的风光，若想达到这般境界，需苦练才行呐。]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc008"]={["age"]=46,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[周其民是这一代圣火居的执法长老。他身世坎坷，年轻时在京城进学，但屡试不第；他为人处世坚持原则甚至有些迂腐，同门都称他为周夫子。]],["family"]=[[mingjiao]],["id"]=[[tasknpc008]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=20,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[周其民]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[不要在意世人的眼光，他们是不会理解我们明教的事业的。;愿以圣火燃此残躯。]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc009"]={["age"]=54,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[呼罗单是西域来的番僧，驻锡于雪山寺已经有三十余年，是本门的客卿长老。]],["family"]=[[mizong]],["id"]=[[tasknpc009]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=17,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[呼罗单]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[耐得住寂寞的人，才会有出息。;我曾枯坐二十载，不求佛法不求缘。]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=-100},["tasknpc010"]={["age"]=43,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[慕容远安是燕氏一脉的远房旁支，他武艺高强，年富力强，近些年来在龙城山庄的地位水涨船高。]],["family"]=[[murong]],["id"]=[[tasknpc010]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=19,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[慕容远安]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[有些事情，做得，说不得。;我燕氏皇族的希望都在慕容业身上了..]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc011"]={["age"]=38,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[麦志农是全真教的名宿。他是真正受过戒的道士，严守清规戒律，在门派中深受后辈们的敬重。]],["family"]=[[quanzhen]],["id"]=[[tasknpc011]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=21,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[麦志农]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[我平生有两大宏愿，一愿天下太平，二愿我全真发扬光大。;莫寻玄妙。我分明说破，修行关窍。战睡敌魔，忘情绝念，此是圣贤正教。]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc012"]={["age"]=37,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[任四海是拜日教近年来崛起的高手之一，他年富力强、敢于任事，深受教主器重。]],["family"]=[[riyueshenjiao]],["id"]=[[tasknpc012]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=20,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[任四海]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[行走江湖，要时刻记得给教长脸，别堕了教的威名。;废物就自裁吧，教不养闲人！]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=-100},["tasknpc013"]={["age"]=36,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[净悟禅师是菩提院首座，他正当壮年，武功和身体状态都处在人生的巅峰，执掌菩提院以来，诸般事务都被他打理的井井有条。]],["family"]=[[shaolin]],["id"]=[[tasknpc013]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=19,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[净悟禅师]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[我少林弟子行走江湖，要谨言慎行，不可污了佛门清誉。;阿弥陀佛，因果循环，报应不爽。;少林多年前因周天功遭受大厄，如此周天功再现于世，一切都是劫数，我少林自当全力化解。]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc014"]={["age"]=42,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[唐四寿是唐门上一辈的传奇人物之一，他的暗器功夫在鼎盛时据说不输于任何人，是公认的练武天赋最好的几个人之一。]],["family"]=[[tangmen]],["id"]=[[tasknpc014]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=25,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[唐四寿]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[江湖上能与门主唐不平交手而不败的高手，一个手就能数过来。]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc015"]={["age"]=35,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[祝雨同是蓬莱岛的名宿，他常年住在落英湾。他武功高强，但因为极少在江湖上走动，所以听说过他名字的人不多。]],["family"]=[[taohuadao]],["id"]=[[tasknpc015]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=24,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[祝雨同]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[在岛上练功习武，把酒言欢，好不快活。]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc016"]={["age"]=37,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[邱堂主本名邱亦钧，是伏龙山的堂主之一，近年来开始执掌聚义庄。据说他与海鲸帮某位高手之间有着不可化解的深仇大恨。]],["family"]=[[tiezhang]],["id"]=[[tasknpc016]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=21,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[邱堂主]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[伏龙山的威名不是吹出来的，是靠一双铁掌打出来的。;海鲸帮这等杂碎，我早晚必灭之！]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=-100},["tasknpc017"]={["age"]=42,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[冲明道长常驻三清殿，是武当派的知客长老，负责各种迎来送往的俗务。]],["family"]=[[wudang]],["id"]=[[tasknpc017]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=22,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[冲明道长]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[天地不仁，以万物为刍狗。;天之道利而不害，圣人之道为而不争，这江湖之上又有几人能做到呢？]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc018"]={["age"]=32,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[何俐珠是万灵谷的名宿，江湖人称其“何仙姑”，除了貌美，还因为她一手出神入化的下毒用毒的功夫和喜怒无常神鬼莫测的怪脾气。]],["family"]=[[wudu]],["id"]=[[tasknpc018]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=28,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[何俐珠]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[女]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[记住了，小姐姐我永远十八岁！;我美吗？啊？！]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=-200},["tasknpc019"]={["age"]=32,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[御风子是虚渺宫近年来崛起的高手，他轻功高超，剑法和拳脚功夫也很精妙，有人断言，他是将来最有希望执掌虚渺宫的几个人之一。]],["family"]=[[tianshan]],["id"]=[[tasknpc019]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=26,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[御风子]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[男]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[我的名号很拉风？是我师尊给起的。;边风飘飘那可度，绝域苍茫更何有！;乘天地之正，御六气之辩，以游于无穷！]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=50},["tasknpc020"]={["age"]=32,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[花鸽子是天狼教高手，有种魔头一般的性格和武功，许多江湖少侠都曾被她玩弄于股掌之中，许多人谈之色变，就算在同门中口碑也不是很好。]],["family"]=[[xingxiu]],["id"]=[[tasknpc020]],["int"]=450,["learn"]=0,["level"]=-10,["looks"]=24,["losetext"]=[[你输了]],["lv"]=500,["name"]=[[花鸽子]],["neili"]=50000,["powerNeili"]=1300,["qi"]=25000,["sex"]=[[女]],["skillexp"]=875000,["str"]=450,["talk"]=1,["talkText"]=[[从前你们叫我大师姐，现在你们叫我花鸽子，这让人如何能忍受得了。;邢慧只不过是沾了师傅的光而已，若论实力，我毫不惧她！]],["task"]=1,["wintext"]=[[你赢了]],["zhengqi"]=-100},["tasknpc021"]={["age"]=33,["appoint"]=0,["baishi"]=0,["canSee"]=1,["compare"]=0,["con"]=450,["dex"]=450,["dsc"]=[[牙牧烟是镇守伏羲阁的崆峒派长老。他年富力强，武功超群，同时还有着不错的手腕和交际能力，是崆峒派对外的一块活招牌。]],["family"]=[[kongtong]],["id"]=[[tasknpc021]],["int"]